svg.script:
const hash = window.location.hash.slice(1);
const config = await (await fetch("https://cdn.jsdelivr.net/gh/marble892/eaglercraft-jsdelivr@latest/config.json")).json();
const versions = config["versions"]
const hashnames = versions.map(entry=>entry.hashname);
let blob;
if(hashnames.includes(hash)) {
    const entry = versions.find(e=>e.hashname===hash);
    const parts = await Promise.all(entry.files.map(url=>fetch(`https://cdn.jsdelivr.net/gh/marble892/eaglercraft-jsdelivr@latest/parts/${url}`)))
    const blobs = await Promise.all(parts.map(res=>res.blob()));
    blob = new Blob(blobs,{type:"text/html"});
} else {
    blob = new Blob([await (await fetch("https://cdn.jsdelivr.net/gh/marble892/eaglercraft-jsdelivr@latest/index.html")).text()],{type:"text/html"});
}
window.location.href = URL.createObjectURL(blob)
